import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3, mix, smoothstep, uniform, fract, sin } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, PlaneGeometry, Color } = THREE;

  const group = new Group();
  group.name = 'hub-features-card-2';

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const inkColor = new Color(colors.ink);
  const surfaceColor = new Color(colors.surface);
  const accentColor = new Color(colors.accent);

  const surfaceUni = uniform(surfaceColor);
  const inkUni = uniform(inkColor);
  const accentUni = uniform(accentColor);

  const cleanups = [];

  // ── BACKDROP: engineered vertical gradient (surface → ink) ──────────────
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial({ transparent: true, toneMapped: false });
  backdropMat.colorNode = mix(
    surfaceUni,
    inkUni,
    smoothstep(0.0, 1.0, uv().y)
  );
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);

  // ── GRAIN: subtle static filmic noise ───────────────────────────────────
  const grainGeo = new PlaneGeometry(7, 6);
  const grainMat = new MeshBasicNodeMaterial({ transparent: true, toneMapped: false });
  const grainVal = fract(sin(uv().x.mul(420.0).add(uv().y.mul(420.0))).mul(43758.5453));
  grainMat.colorNode = vec3(grainVal);
  grainMat.opacityNode = uniform(0.022);
  const grain = new Mesh(grainGeo, grainMat);
  grain.position.set(0, 0, -2.4);
  group.add(grain);

  // ── ACCENT GLOW: radial halo behind sprite (≤10% frame accent) ──────────
  const glowW = 3.4;
  const glowH = 2.8;
  const glowGeo = new PlaneGeometry(glowW, glowH);
  const glowMat = new MeshBasicNodeMaterial({ transparent: true, toneMapped: false });
  const glowDist = uv().sub(vec2(0.5, 0.5)).length();
  glowMat.colorNode = accentUni;
  glowMat.opacityNode = smoothstep(0.55, 0.05, glowDist).mul(0.08);
  const glow = new Mesh(glowGeo, glowMat);
  glow.position.set(0, 0, -0.2);
  group.add(glow);

  // ── SPRITE: floating accent texture, billboarded (+Z faces camera) ──────
  const atlasW = 512;
  const atlasH = 320;
  const aspectRatio = atlasW / atlasH; // 1.6
  const spriteW = 2.2;
  const spriteH = spriteW / aspectRatio; // 1.375

  const spriteGeo = new PlaneGeometry(spriteW, spriteH);
  const spriteMat = new MeshBasicNodeMaterial({
    transparent: true,
    toneMapped: false
  });

  // Atlas region UV mapping: source rect 0,0,512,320 → full texture
  const atlasSourceRect = config.atlasRegion?.sourceRect ?? { x: 0, y: 0, w: atlasW, h: atlasH };
  const sx = atlasSourceRect.x ?? 0;
  const sy = atlasSourceRect.y ?? 0;
  const sw = atlasSourceRect.w ?? atlasW;
  const sh = atlasSourceRect.h ?? atlasH;
  const fullAtlasW = config.atlasRegion?.fullWidth ?? atlasW;
  const fullAtlasH = config.atlasRegion?.fullHeight ?? atlasH;
  if (sw < fullAtlasW || sh < fullAtlasH || sx > 0 || sy > 0) {
    // Sub-region extraction
    const uOffset = sx / fullAtlasW;
    const vOffset = 1.0 - (sy + sh) / fullAtlasH;
    const uRepeat = sw / fullAtlasW;
    const vRepeat = sh / fullAtlasH;
    spriteMat.mapNode = null; // will set via texture
    // Store for deferred texture application
    sprite.userData._atlasUV = { uOffset, vOffset, uRepeat, vRepeat };
  }

  const sprite = new Mesh(spriteGeo, spriteMat);
  sprite.position.set(0, 0, 0);
  group.add(sprite);

  // Load texture asynchronously
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = THREE.SRGBColorSpace;
      tex.minFilter = THREE.LinearFilter;
      tex.magFilter = THREE.LinearFilter;
      tex.generateMipmaps = false;

      if (sprite.userData._atlasUV) {
        const { uOffset, vOffset, uRepeat, vRepeat } = sprite.userData._atlasUV;
        tex.offset.set(uOffset, vOffset);
        tex.repeat.set(uRepeat, vRepeat);
        tex.needsUpdate = true;
      }

      spriteMat.map = tex;
      spriteMat.needsUpdate = true;
    });
  }

  // ── MOTION: weighted-settle entrance + subtle breathing ─────────────────
  const entranceTl = gsap.timeline();
  entranceTl.from(sprite.position, {
    y: 0.35,
    duration: 0.7,
    ease: 'power3.out'
  });
  entranceTl.from(glow.position, {
    y: 0.35,
    duration: 0.7,
    ease: 'power3.out'
  }, 0);
  entranceTl.from(sprite.scale, {
    x: 0.96, y: 0.96, z: 0.96,
    duration: 0.9,
    ease: 'power4.out'
  }, 0);
  entranceTl.to(sprite.scale, {
    x: 1.0, y: 1.0, z: 1.0,
    duration: 0.0
  });

  // Idle breathing (≤2% scale, slow)
  const breatheTl = gsap.timeline({ repeat: -1, yoyo: true });
  breatheTl.to(sprite.scale, {
    x: 1.018, y: 1.018, z: 1.018,
    duration: 3.6,
    ease: 'sine.inOut'
  });

  // Glow pulse synced with breathing
  const glowTl = gsap.timeline({ repeat: -1, yoyo: true });
  glowTl.to(glow.scale, {
    x: 1.05, y: 1.05,
    duration: 3.6,
    ease: 'sine.inOut'
  });

  // ── HANDLERS (none — static composition) ────────────────────────────────
  group.userData.handlers = {};

  // ── CLEANUP ─────────────────────────────────────────────────────────────
  group.userData.cleanup = () => {
    entranceTl.kill();
    breatheTl.kill();
    glowTl.kill();
    backdropGeo.dispose();
    backdropMat.dispose();
    grainGeo.dispose();
    grainMat.dispose();
    glowGeo.dispose();
    glowMat.dispose();
    spriteGeo.dispose();
    spriteMat.dispose();
  };

  return group;
}
